{
 "driver_archetypes": [
  {
   "id": "car_compliant",
   "base_vclass": "passenger",
   "distribution": "car",
   "share": 0.82,
   "params": {
    "tau": 1.5,
    "minGap": 2.8,
    "accel": 2.6,
    "decel": 4.5,
    "sigma": 0.5,
    "speedFactor": 1.0,
    "latAlignment": "right"
   },
   "rationale": "Standard compliant car behavior targeting M1/car discharge headway (lowering from 0.97 to ~0.35)."
  },
  {
   "id": "car_early_starter",
   "base_vclass": "passenger",
   "distribution": "car",
   "share": 0.18,
   "params": {
    "tau": 1.2,
    "minGap": 2.5,
    "accel": 2.6,
    "decel": 4.5,
    "sigma": 0.3,
    "speedFactor": 1.0,
    "latAlignment": "right"
   },
   "rationale": "Impatient car archetype to increase early-start share (targeting M2/early/car 0.011) and reduce first delay."
  },
  {
   "id": "moto_compliant",
   "base_vclass": "motorcycle",
   "distribution": "moto",
   "share": 0.25,
   "params": {
    "tau": 1.0,
    "minGapLat": 0.6,
    "maxSpeedLat": 1.5,
    "latAlignment": "right",
    "lcSublane": 0.0,
    "lcPushy": 0.0
   },
   "rationale": "Standard motorcycle behavior targeting M1/moto discharge headway (lowering from 0.6 to ~0.3)."
  },
  {
   "id": "moto_slow_center",
   "base_vclass": "motorcycle",
   "distribution": "moto",
   "share": 0.45,
   "params": {
    "tau": 1.0,
    "minGapLat": 0.8,
    "maxSpeedLat": 0.9,
    "latAlignment": "center",
    "lcSublane": 2.0,
    "lcPushy": 0.0
   },
   "rationale": "Slow motorcycle archetype riding in lane center (targeting M4/lat_moto 7.19m and M4/overshoot_share 62%)."
  },
  {
   "id": "moto_sidewalk",
   "base_vclass": "motorcycle",
   "distribution": "moto",
   "share": 0.30,
   "params": {
    "tau": 1.0,
    "minGapLat": 0.5,
    "maxSpeedLat": 2.0,
    "latAlignment": "arbitrary",
    "lcSublane": 4.5,
    "lcPushy": 0.8,
    "lcMaxSpeedLatStanding": 3.0
   },
   "rationale": "Aggressive motorcycle archetype to utilize wrong lanes/sidewalks and reduce queue lengths (targeting M10a sidewalk usage and M5 queue length)."
  },
  {
   "id": "moto_violator_left",
   "base_vclass": "custom1",
   "distribution": "moto_violator",
   "share": 1.0,
   "params": {
    "tau": 1.8,
    "minGap": 2.5,
    "accel": 6.0,
    "decel": 10.0,
    "sigma": 0.3,
    "speedFactor": 1.0,
    "latAlignment": "arbitrary",
    "lcSublane": 4.5,
    "lcPushy": 0.9,
    "jmTimegapMinor": 2.0
   },
   "rationale": "Violating motorcycle archetype for illegal left turns from HDT_N/S and queue seeking (targeting M6 entry times and M7 box clearance)."
  },
  {
   "id": "car_violator",
   "base_vclass": "custom2",
   "distribution": "car",
   "share": 0.18,
   "params": {
    "tau": 1.5,
    "minGap": 2.5,
    "accel": 2.6,
    "decel": 4.5,
    "sigma": 0.3,
    "speedFactor": 1.0,
    "latAlignment": "arbitrary",
    "lcSublane": 2.0,
    "lcPushy": 0.6
   },
   "rationale": "Violating car archetype to capture M8/wrong-lane share (targeting 0.068)."
  }
 ],
 "traci_rules": [
  {
   "rule_type": "early_start",
   "applies_to": [
    "car_compliant",
    "car_early_starter"
   ],
   "params": {
    "t_before_green": 4,
    "p": 0.15,
    "v_max": 3.0
   },
   "rationale": "Controls early start creep before green for cars to match M2/early/car share (increased probability and window)."
  },
  {
   "rule_type": "swarm_red_running",
   "applies_to": [
    "moto_violator_left"
   ],
   "params": {
    "p0": 0.3,
    "k": 0.25,
    "p_max": 0.6,
    "dt": 10
   },
   "rationale": "Models swarm pressure for red-light running among violating motorcycles (targeting M3/share/moto 9.8%)."
  },
  {
   "rule_type": "illegal_left_box",
   "applies_to": [
    "moto_violator_left"
   ],
   "params": {
    "release_lag_s": 0.5
   },
   "rationale": "Reduces extra hold time for illegal left-turning motorcycles to better match M6/junction/illegal_l/moto timing and reduce box occupancy."
  },
  {
   "rule_type": "queue_space_seeking",
   "applies_to": [
    "moto_sidewalk",
    "moto_violator_left"
   ],
   "params": {
    "q": 60,
    "t_g_s": 15,
    "est_noise": 0.4,
    "p_wrong_lane": 0.6,
    "p_right_lane": 0.0,
    "p_sidewalk": 0.3,
    "v_creep": 2.5,
    "merge_zone_m": 15
   },
   "rationale": "Triggers lateral maneuvering (wrong lane or sidewalk) when queues are long or green is approaching to reduce M5 queue length and increase M10a sidewalk usage."
  },
  {
   "rule_type": "uturn_bypass",
   "applies_to": [
    "car_compliant",
    "moto_compliant",
    "moto_violator_left"
   ],
   "params": {
    "p": 0.85,
    "t_wait": 2
   },
   "rationale": "Allows motorcycles (especially moto_violator and compliant) to squeeze past standing U-turners while cars rarely do (targeting M11 behavior)."
  }
 ],
 "description": "Rebalanced archetype shares to sum distributions correctly, increased aggressive motorcycle presence for queue/sidewalk usage, tuned early-start probability, reduced red-light swarm cap, lowered illegal-left hold time, and enabled wrong-lane maneuvers via queue_space_seeking."
}

